CREATE OR REPLACE FUNCTION public.master_v2_lock_scope(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform combat_consumer_private.lock_narrative_control(p_session);
  perform 1 from public.master_v2_sessions m where m.id=p_session for update;
  if not found then
    perform public.combat_v2_fail('sessione_inesistente','Sessione Master inesistente.',404,null,'{}');
  end if;
  perform 1 from public.combat_v2_sessions s
   where s.master_session_id=p_session order by s.id for update;
  perform 1 from public.combat_v2_rounds r
   join public.combat_v2_sessions s on s.id=r.session_id
   where s.master_session_id=p_session order by r.id for update of r;
  perform 1 from public.combat_v2_actors a
   join public.combat_v2_sessions s on s.id=a.session_id
   where s.master_session_id=p_session order by a.id for update of a;
  perform 1 from public.characters c
   where c.id in (
     select a.character_id from public.combat_v2_actors a
     join public.combat_v2_sessions s on s.id=a.session_id
     where s.master_session_id=p_session and a.character_id is not null
   ) order by c.id for update;
end $function$

