CREATE OR REPLACE FUNCTION combat_consumer_private.lock_narrative_control(p_master uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid; rid uuid;
begin
  select a.session_id into sid from combat_consumer_private.narrative_authorities a where master_session_id=p_master;
  if sid is null then return; end if;
  -- Sessione stabile prima di leggere l'exchange: una pubblicazione può averlo cambiato.
  perform 1 from public.combat_v2_sessions where id=sid for update;
  select exchange_id into rid from combat_consumer_private.activities where session_id=sid;
  perform public.combat_v2_lock_round(rid);
end $function$

