CREATE OR REPLACE FUNCTION public.combat_v2_lock_round(p_round uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_session uuid; v_master uuid;
begin
  select r.session_id,s.master_session_id into v_session,v_master
    from public.combat_v2_rounds r
    join public.combat_v2_sessions s on s.id=r.session_id
   where r.id=p_round;
  if v_session is null then
    perform public.combat_v2_fail('sessione_inesistente','Round inesistente.',404,null,'{}');
  end if;
  if v_master is not null then
    perform public.master_v2_lock_scope(v_master);
  else
    perform 1 from public.combat_v2_sessions s where s.id=v_session for update;
    perform 1 from public.combat_v2_rounds r where r.id=p_round for update;
    perform 1 from public.combat_v2_actors a where a.session_id=v_session order by a.id for update;
    perform 1 from public.characters c where c.id in (
      select a.character_id from public.combat_v2_actors a
       where a.session_id=v_session and a.character_id is not null
    ) order by c.id for update;
  end if;
end $function$

